styles:
:root{--bg:#070707;--bg2:#0d0d0d;--paper:#f1eee7;--paper2:#e6e2da;--ink:#0a0a0a;--text:#f4f2ee;--muted:#a39f98;--red:#e81848;--line:rgba(255,255,255,.14);--lineD:rgba(10,10,10,.15);--max:1480px;--pad:clamp(20px,3.35vw,58px);--ease:cubic-bezier(.16,1,.3,1);--display:"Helvetica Neue",Helvetica,Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--display);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}a{color:inherit;text-decoration:none}button{font:inherit}img{display:block;width:100%;height:auto}figure{margin:0}.shell{width:min(var(--max),100%);margin-inline:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:var(--ink);padding:10px 14px;transform:translateY(-140%);transition:.2s}.skip:focus{transform:none}.nav{height:82px;position:fixed;z-index:90;top:0;left:0;right:0;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,7,7,.8);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}.brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:-.04em;font-size:18px}.brand-mark{width:29px;height:29px;object-fit:contain}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{color:#d8d5d0;transition:color .2s}.nav-links a:hover,.nav-links a:focus-visible,.nav-links a[aria-current=page]{color:#fff}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px;transition:background .25s var(--ease),color .25s var(--ease)!important}.nav-cta:hover{background:#fff;color:#0a0a0a!important}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);color:white;align-items:center;justify-content:center;cursor:pointer;position:relative}.menu-btn span,.menu-btn:before{content:"";display:block;width:18px;height:1px;background:currentColor;position:absolute}.menu-btn span{transform:translateY(4px)}.menu-btn:before{transform:translateY(-4px)}.mobile-menu{display:none;position:fixed;inset:82px 0 0;z-index:80;background:#070707;padding:32px var(--pad) 40px}.mobile-menu.open{display:block}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}
.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.19em;color:var(--muted)}.btn{display:inline-flex;min-height:48px;align-items:center;justify-content:center;gap:10px;padding:13px 19px;border:1px solid rgba(255,255,255,.25);font-size:13px;transition:transform .25s var(--ease),background .25s var(--ease),border-color .25s var(--ease)}.btn.primary{background:var(--red);border-color:var(--red)}.btn:hover{transform:translateY(-2px);border-color:#fff}.btn.primary:hover{background:#f12557}.text-link{font-size:13px;border-bottom:1px solid currentColor;padding:11px 0;min-height:44px;display:inline-flex;gap:12px;align-items:center}.reveal{opacity:0;transform:translateY(26px);transition:opacity .8s var(--ease),transform .8s var(--ease)}.reveal.in{opacity:1;transform:none}
/* hero — editorial pinned scene */
.hero{height:178svh;position:relative;overflow:clip;--hp:0}.hero-stage{position:sticky;top:0;height:100svh;padding-top:82px;display:flex;align-items:flex-end;overflow:hidden;background:#070707}.hero-stage:before{content:"";position:absolute;inset:82px 0 auto;height:1px;background:linear-gradient(90deg,transparent 0 4%,rgba(255,255,255,.11) 4% 96%,transparent 96%)}.hero-stage:after{content:"";position:absolute;right:-7vw;top:16vh;width:min(42vw,620px);aspect-ratio:1;background:url('assets/aroz-a-mark.png') center/contain no-repeat;opacity:.035;transform:rotate(-8deg);pointer-events:none}.hero .shell{padding-top:clamp(54px,6vw,92px);padding-bottom:clamp(30px,3.8vw,54px)}.hero-meta{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:clamp(26px,3.2vw,44px)}.hero-meta span:last-child{font-size:12px;color:#817d77}.hero-grid{display:grid;grid-template-columns:1.03fr .97fr;gap:clamp(42px,6vw,110px);align-items:end}.hero h1{font-size:clamp(68px,8.2vw,132px);line-height:.84;letter-spacing:-.073em;font-weight:540;margin:0;max-width:850px}.hero h1 .mark{position:relative;display:inline-block}.hero h1 .mark:after{content:"";position:absolute;left:.04em;bottom:-.10em;width:clamp(42px,5vw,82px);height:clamp(5px,.46vw,8px);background:var(--red);transform-origin:left;transform:scaleX(calc(.55 + var(--hp)*.45))}.hero-lead{font-size:clamp(18px,1.4vw,23px);line-height:1.43;color:#c8c4bd;margin:0 0 28px;max-width:560px;letter-spacing:-.02em}.hero-actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.hero-index{margin-top:clamp(50px,6vw,82px);border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(4,1fr)}.hero-index-item{position:relative;min-height:154px;padding:18px 18px 20px 0;border-right:1px solid var(--line);color:#5f5b56;transition:color .45s var(--ease),transform .55s var(--ease),background .55s var(--ease)}.hero-index-item:last-child{border-right:0;padding-right:0}.hero-index-item:before{content:"";position:absolute;left:0;top:-1px;width:0;height:2px;background:var(--red);transition:width .55s var(--ease)}.hero-index-item .n{display:block;font-size:9px;letter-spacing:.16em;text-transform:uppercase;margin-bottom:42px;color:inherit}.hero-index-item strong{display:block;font-size:clamp(22px,2.2vw,34px);font-weight:500;letter-spacing:-.04em;color:inherit}.hero-index-item small{display:block;margin-top:8px;font-size:11px;line-height:1.45;color:#6f6a64;max-width:170px}.hero-stage[data-state="1"] .hero-index-item:nth-child(1),.hero-stage[data-state="2"] .hero-index-item:nth-child(2),.hero-stage[data-state="3"] .hero-index-item:nth-child(3),.hero-stage[data-state="4"] .hero-index-item:nth-child(4){color:#f1eee7;transform:translateY(-4px)}.hero-stage[data-state="1"] .hero-index-item:nth-child(1):before,.hero-stage[data-state="2"] .hero-index-item:nth-child(2):before,.hero-stage[data-state="3"] .hero-index-item:nth-child(3):before,.hero-stage[data-state="4"] .hero-index-item:nth-child(4):before{width:48px}.hero-endnote{position:absolute;right:var(--pad);bottom:18px;font-size:9px;letter-spacing:.15em;text-transform:uppercase;color:#5b5752}.hero-endnote b{font-weight:500;color:#8f8a83}

/* context — editorial reading surface */
.context{background:#0a0a0a;padding:clamp(115px,11vw,180px) 0;position:relative;overflow:clip}.context:before{content:"";position:absolute;left:-12vw;top:19%;width:52vw;height:52vw;background:url('assets/aroz-slash.png') center/contain no-repeat;opacity:.025;transform:rotate(-7deg);pointer-events:none}.context-head{display:grid;grid-template-columns:.34fr 1.66fr;gap:clamp(36px,7vw,118px);margin-bottom:70px}.context-head h2{font-size:clamp(48px,6.4vw,100px);line-height:.92;letter-spacing:-.061em;font-weight:520;margin:0;max-width:1000px}.context-story{height:330svh;position:relative}.context-pin{position:sticky;top:82px;height:calc(100svh - 82px);display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(36px,6vw,92px);align-items:center;overflow:hidden}.context-canvas{height:min(67vh,650px);position:relative;overflow:visible}.context-page{position:absolute;inset:0;background:var(--paper);color:#11100f;box-shadow:0 24px 80px rgba(0,0,0,.28);padding:clamp(24px,3.4vw,48px);display:grid;grid-template-columns:88px 1fr 150px;grid-template-rows:auto 1fr auto;column-gap:clamp(20px,3vw,44px);overflow:hidden;transition:transform .7s var(--ease),box-shadow .7s var(--ease)}.context-page:before{content:"";position:absolute;left:88px;top:0;bottom:0;width:1px;background:rgba(17,16,15,.11)}.context-page:after{content:"";position:absolute;right:150px;top:0;bottom:0;width:1px;background:rgba(17,16,15,.08)}.context-page-meta{grid-column:1/-1;display:flex;justify-content:space-between;padding-bottom:18px;border-bottom:1px solid rgba(17,16,15,.16);font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:#6e6962}.context-page-index{grid-column:1;grid-row:2;padding-top:34px;display:flex;flex-direction:column;gap:16px;font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:#8a847b}.context-page-index span{position:relative;padding-left:14px;transition:color .4s var(--ease),transform .4s var(--ease)}.context-page-index span:before{content:"";position:absolute;left:0;top:.55em;width:5px;height:1px;background:#9d978e;transition:width .4s var(--ease),background .4s}.context-page-main{grid-column:2;grid-row:2;padding-top:34px;display:flex;flex-direction:column;justify-content:space-between}.context-page-main h3{font-size:clamp(38px,4.7vw,76px);line-height:.91;letter-spacing:-.06em;font-weight:520;margin:0;max-width:620px}.context-page-main p{font-size:clamp(16px,1.3vw,20px);line-height:1.48;max-width:560px;color:#504c46;margin:28px 0 0}.context-copylines{margin-top:auto;padding-top:40px;display:grid;gap:10px}.context-copylines i{display:block;height:1px;background:#bdb6ad;transform-origin:left;transition:transform .65s var(--ease),opacity .4s}.context-copylines i:nth-child(1){width:84%}.context-copylines i:nth-child(2){width:72%}.context-copylines i:nth-child(3){width:91%}.context-copylines i:nth-child(4){width:54%}.context-page-margin{grid-column:3;grid-row:2;padding-top:34px;display:flex;flex-direction:column;gap:14px}.context-note{padding:0 0 12px 12px;border-left:1px solid #c8c0b7;font-size:9px;line-height:1.35;letter-spacing:.13em;text-transform:uppercase;color:#7b756d;opacity:.28;transform:translateX(0);transition:opacity .45s var(--ease),color .45s,border-color .45s,transform .45s}.context-page-footer{grid-column:1/-1;grid-row:3;border-top:1px solid rgba(17,16,15,.16);padding-top:16px;display:flex;justify-content:space-between;align-items:center;font-size:9px;text-transform:uppercase;letter-spacing:.15em;color:#716b64}.context-page-footer strong{font-weight:500;color:#11100f}.context-pin[data-state="1"] .context-page-index span:nth-child(1),.context-pin[data-state="2"] .context-page-index span:nth-child(2),.context-pin[data-state="3"] .context-page-index span:nth-child(3),.context-pin[data-state="4"] .context-page-index span:nth-child(4){color:#11100f;transform:translateX(4px)}.context-pin[data-state="1"] .context-page-index span:nth-child(1):before,.context-pin[data-state="2"] .context-page-index span:nth-child(2):before,.context-pin[data-state="3"] .context-page-index span:nth-child(3):before,.context-pin[data-state="4"] .context-page-index span:nth-child(4):before{width:9px;background:var(--red)}.context-pin[data-state="2"] .context-copylines i{transform:scaleX(.94)}.context-pin[data-state="3"] .context-note{opacity:1;color:#282521;border-color:var(--red);transform:translateX(3px)}.context-pin[data-state="4"] .context-page{transform:translateY(-4px);box-shadow:0 34px 95px rgba(0,0,0,.36)}.context-pin[data-state="4"] .context-page-footer strong{color:var(--red)}.context-copy{position:relative;height:430px}.context-copy article{display:none;position:absolute;inset:0;pointer-events:none}.context-copy article.active{display:block;pointer-events:auto;animation:contextIn .42s var(--ease) both}@keyframes contextIn{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}.context-copy .n{font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:var(--red)}.context-copy h3{font-size:clamp(38px,4.5vw,72px);line-height:.94;letter-spacing:-.057em;font-weight:510;margin:22px 0 26px}.context-copy p{font-size:clamp(17px,1.35vw,21px);line-height:1.5;color:#b8b3ac;max-width:580px}.context-progress{position:absolute;left:0;bottom:0;right:0;height:1px;background:rgba(255,255,255,.13)}.context-progress i{height:1px;background:var(--red);display:block;width:25%;transition:width .55s var(--ease)}.context-triggers{height:100%;display:grid;grid-template-rows:repeat(4,1fr)}

/* routes */
.routes{background:var(--paper);color:var(--ink);padding:clamp(110px,11vw,180px) 0}.routes-head{display:grid;grid-template-columns:.34fr 1.66fr;gap:clamp(36px,7vw,118px);margin-bottom:70px}.routes-head h2{font-size:clamp(52px,6.8vw,108px);line-height:.9;letter-spacing:-.064em;font-weight:530;margin:0;max-width:1080px}.route-list{border-top:1px solid var(--lineD)}.route{display:grid;grid-template-columns:80px 1.1fr 1fr 80px;gap:24px;align-items:center;min-height:154px;border-bottom:1px solid var(--lineD);transition:padding .35s var(--ease),background .35s}.route:hover{padding-inline:14px;background:#e9e5dd}.route .num{font-size:11px;color:#77716b}.route h3{font-size:clamp(30px,3.1vw,48px);font-weight:510;letter-spacing:-.048em;margin:0}.route p{font-size:15px;max-width:530px;color:#55514c;margin:0}.route .arrow{justify-self:end;font-size:25px}.route:hover .arrow{transform:translate(4px,-4px)}
/* entity editorial */
.entities{padding:clamp(115px,11vw,180px) 0;background:#090909;position:relative;overflow:hidden}.entities-mark{position:absolute;width:min(40vw,560px);right:-7vw;bottom:-18%;opacity:.045;pointer-events:none}.entities-grid{display:grid;grid-template-columns:.77fr 1.23fr;gap:clamp(48px,7vw,116px)}.entities h2{font-size:clamp(50px,6.7vw,104px);line-height:.9;letter-spacing:-.064em;font-weight:520;margin:0 0 34px}.entities-copy p{font-size:clamp(18px,1.4vw,22px);color:#b9b4ad;max-width:650px}.entity-ledger{border-top:1px solid var(--line)}.ledger-row{display:grid;grid-template-columns:70px 1fr auto;gap:24px;align-items:center;border-bottom:1px solid var(--line);min-height:96px}.ledger-row span{font-size:10px;color:#74706a}.ledger-row strong{font-size:clamp(24px,2.2vw,34px);font-weight:500;letter-spacing:-.04em}.ledger-row i{font-style:normal;font-size:10px;text-transform:uppercase;letter-spacing:.15em;color:#706c66}.ledger-row:nth-child(2) strong{color:var(--red)}
/* bridge */
.bridge{background:var(--paper2);color:var(--ink);padding:clamp(110px,10vw,165px) 0}.bridge-head{display:grid;grid-template-columns:.34fr 1.66fr;gap:clamp(36px,7vw,118px);margin-bottom:62px}.bridge-head h2{font-size:clamp(48px,6.3vw,96px);line-height:.91;letter-spacing:-.061em;font-weight:520;margin:0;max-width:1050px}.bridge-grid{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--lineD);border-bottom:1px solid var(--lineD)}.bridge-col{padding:44px 6vw 46px 0}.bridge-col+ .bridge-col{border-left:1px solid var(--lineD);padding-left:6vw}.bridge-col small{font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:#77716a}.bridge-col h3{font-size:clamp(34px,4vw,62px);letter-spacing:-.055em;font-weight:520;margin:18px 0 24px}.bridge-col p{font-size:16px;color:#56514c;max-width:560px}.bridge-base{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px}.bridge-base span{border:1px solid var(--lineD);padding:8px 10px;font-size:10px;text-transform:uppercase;letter-spacing:.12em}
/* analysis */
.analysis{background:#070707;padding:clamp(110px,10vw,165px) 0}.analysis-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:clamp(40px,7vw,110px);align-items:center}.analysis-media{position:relative;overflow:hidden;min-height:540px}.analysis-media img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0;filter:saturate(.88) contrast(1.02)}.analysis-media:after{content:"";position:absolute;left:0;right:0;bottom:0;height:32%;background:linear-gradient(transparent,rgba(0,0,0,.55))}.analysis-copy h2{font-size:clamp(48px,6vw,92px);line-height:.91;letter-spacing:-.062em;font-weight:520;margin:18px 0 30px}.analysis-copy p{font-size:clamp(17px,1.35vw,21px);line-height:1.5;color:#bcb7b0;max-width:620px;margin-bottom:32px}
.final{background:var(--red);color:#fff;padding:clamp(95px,9vw,145px) 0}.final-top{font-size:10px;text-transform:uppercase;letter-spacing:.16em;opacity:.78}.final h2{font-size:clamp(58px,8.3vw,132px);line-height:.85;letter-spacing:-.071em;font-weight:540;margin:38px 0 54px;max-width:1200px}.final-row{display:grid;grid-template-columns:1fr auto;gap:40px;align-items:end;border-top:1px solid rgba(255,255,255,.32);padding-top:25px}.final-row p{font-size:17px;max-width:610px;margin:0}.final .btn{border-color:#fff;background:#fff;color:#0a0a0a}
.footer{background:#070707;padding:72px 0 30px}.footer-top{display:grid;grid-template-columns:1fr 1.45fr;gap:80px;padding-bottom:66px}.footer-brand{font-size:clamp(54px,6vw,90px);font-weight:600;letter-spacing:-.065em}.footer-top p{color:#8d8983;max-width:300px}.footer-map{display:grid;grid-template-columns:repeat(3,1fr);gap:34px}.footer-map strong{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:#77736c;margin-bottom:17px}.footer-map a{display:block;font-size:13px;color:#c1bdb6;margin:9px 0}.footer-bottom{border-top:1px solid var(--line);padding-top:21px;display:grid;grid-template-columns:1fr auto auto;gap:32px;font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:#68645f}.footer-bottom div{display:flex;gap:20px}
@media(max-width:1050px){.nav-links{display:none}.menu-btn{display:flex}.hero{height:auto}.hero-stage{position:relative;height:auto;min-height:100svh}.hero-grid{grid-template-columns:1fr;align-items:start}.hero-side{max-width:680px}.hero-index{grid-template-columns:repeat(2,1fr)}.hero-index-item:nth-child(2){border-right:0}.hero-index-item{min-height:128px}.context-head,.routes-head,.bridge-head,.manifesto-grid{grid-template-columns:1fr;gap:30px}.context-story{height:300svh}.context-pin{grid-template-columns:1fr;grid-template-rows:minmax(300px,44vh) auto;gap:32px;top:82px;height:calc(100svh - 82px);align-content:center}.context-canvas{height:100%}.context-page{grid-template-columns:68px 1fr 120px;padding:28px}.context-page:before{left:68px}.context-page:after{right:120px}.context-copy{height:270px}.context-copy h3{font-size:clamp(34px,6vw,58px)}.entities-grid,.analysis-grid{grid-template-columns:1fr}.entities-copy{max-width:760px}.analysis-media{min-height:460px}.footer-top{grid-template-columns:1fr}.footer-map{max-width:740px}}
