(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const btn=document.querySelector('.menu-btn'),menu=document.querySelector('.mobile-menu');if(btn&&menu){btn.addEventListener('click',()=>{const open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open));menu.classList.toggle('open',!open);menu.setAttribute('aria-hidden',String(open));document.body.classList.toggle('menu-open',!open)});addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.classList.contains('open')){btn.click();btn.focus()}})}
if(reduce){document.querySelectorAll('.reveal').forEach(e=>e.classList.add('in'));return}
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.13,rootMargin:'0px 0px -6%'});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
const hero=document.querySelector('.hero'),heroStage=document.querySelector('.hero-stage');let ticking=false;function fx(){const vh=innerHeight;if(hero){const r=hero.getBoundingClientRect();const travel=Math.max(1,hero.offsetHeight-vh);const p=innerWidth>1050?Math.max(0,Math.min(1,-r.top/travel)):0;hero.style.setProperty('--hp',p.toFixed(4));const a=Math.min(3,Math.floor(Math.min(.999,p)*4));if(heroStage)heroStage.dataset.state=String(a+1);}ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(fx);ticking=true}},{passive:true});addEventListener('resize',fx,{passive:true});fx();
const story=document.querySelector('.context-story'),pin=document.querySelector('.context-pin'),copies=[...document.querySelectorAll('.context-copy article')],bar=document.querySelector('.context-progress i');function updateContext(){if(!story||!pin)return;const r=story.getBoundingClientRect();const travel=Math.max(1,story.offsetHeight-innerHeight);const p=Math.max(0,Math.min(.999,-r.top/travel));const active=Math.min(3,Math.floor(p*4));pin.dataset.state=String(active+1);copies.forEach((x,i)=>x.classList.toggle('active',i===active));if(bar)bar.style.width=((active+1)*25)+'%'}addEventListener('scroll',updateContext,{passive:true});addEventListener('resize',updateContext,{passive:true});updateContext();
})();
